def is_samepatterns(colors, patterns):
    if len(colors) != len(patterns):
        return False
    c2p, p2c = {}, {}
    for c, p in zip(colors, patterns):
        if c in c2p and c2p[c] != p:
            return False
        if p in p2c and p2c[p] != c:
            return False
        c2p[c] = p
        p2c[p] = c
    return True
